// cos_rando_test_R0_5 (docs/RANDOMIZER_PLAN.md step R0.5): the location key table
// (features/rando/pc_rando_lockeys.h, generated by native/tools/rando/gen_location_keys.py from
// wwrando and the disc). Checks that every location has at least one key and that keys line up with
// R0.3's paths, the per-location classes of the locations report, the fingerprint counts (391 dzx
// items, 11 events, 77 code bytes + 6 boss sites), the field of each actor class, the PCR_LOC_* ids,
// and the field read/write/fingerprint helpers on synthetic entries.
// Prints "ok" and exits 0 when every check holds.
#include "rando_test.h"

#include "pc/pc_rando_locs.h"
#include "pc_rando_data.h"
#include "pc_rando_lockeys.h"

#include <cstring>
#include <map>
#include <set>
#include <string>

using namespace pcr;

namespace {

bool eq(const char* a, const char* b) { return a != nullptr && b != nullptr && std::strcmp(a, b) == 0; }

std::string enumFor(const char* name) {
    std::string s = "PCR_LOC_";
    bool sep = false;
    for (const char* p = name; *p; p++) {
        char c = *p;
        if (c == '\'') {
            continue;
        }
        if (c >= 'a' && c <= 'z') {
            c = (char)(c - 'a' + 'A');
        }
        bool alnum = (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9');
        if (!alnum) {
            sep = true;
            continue;
        }
        if (sep && s.size() > 8) {
            s += '_';
        }
        sep = false;
        s += c;
    }
    return s;
}

// "<stage>/<arc>.arc" of R0.3's path vs the key's stage and arc.
bool sameFile(const LocPath& p, const LocKey& k) {
    std::string f = std::string(k.stage) + "/" + k.arc + ".arc";
    return eq(p.file, f.c_str());
}

void testShape() {
    RT_CHECK_EQ(location_keys().size, loc_paths().size);
    RT_CHECK_EQ(location_keys().size, (size_t)511);
    RT_CHECK_EQ((int)PCR_LOC_COUNT, 320);
    RT_CHECK_EQ(locations().size, (size_t)PCR_LOC_COUNT);

    std::set<std::string> dzxKeys;
    for (int loc = 0; loc < PCR_LOC_COUNT; loc++) {
        const Location& l = locations()[loc];
        Span<LocKey> ks = location_keys(loc);
        RT_CHECK(ks.size >= 1);
        RT_CHECK_EQ(ks.size, (size_t)l.num_paths);
        Span<LocPath> ps = location_paths(l);
        int vanilla = item_id(l.original_item);
        for (size_t i = 0; i < ks.size && i < ps.size; i++) {
            const LocKey& k = ks[i];
            const LocPath& p = ps[i];
            RT_CHECK_EQ((int)k.loc, loc);
            RT_CHECK_EQ((int)k.vanilla, vanilla);
            switch (p.kind) {
            case PathKind::Chest:
            case PathKind::ScalableObject:
            case PathKind::Actor: {
                RT_CHECK(k.kind == KeyKind::Dzx || k.kind == KeyKind::Added);
                RT_CHECK(sameFile(p, k));
                RT_CHECK_EQ((int)k.index, (int)p.index);
                const char* base = p.kind == PathKind::Chest ? "TRE" : p.kind == PathKind::Actor ? "ACT" : "SCO";
                RT_CHECK(std::strncmp(k.tag, base, 3) == 0);
                char last = p.layer < 0 ? (p.kind == PathKind::Chest ? 'S' : p.kind == PathKind::Actor ? 'R' : 'B')
                                        : "0123456789ab"[p.layer];
                RT_CHECK_EQ(k.tag[3], last);
                RT_CHECK(std::strlen(k.tag) == 4);
                RT_CHECK(eq(k.arc, "Stage") || std::strncmp(k.arc, "Room", 4) == 0);
                if (k.kind == KeyKind::Dzx) {
                    std::string id = std::string(k.stage) + "/" + k.arc + "/" + k.tag + "/" + std::to_string(k.index);
                    RT_CHECK(dzxKeys.insert(id).second);
                    RT_CHECK(k.field != DzxField::None);
                    RT_CHECK(k.width == 2 || k.width == 4);
                    RT_CHECK(k.mask != 0 && (k.width == 4 || k.mask <= 0xFFFF));
                    RT_CHECK(k.fp_name[0] != 0);
                } else {
                    RT_CHECK(p.kind == PathKind::Chest && p.layer < 0);
                    RT_CHECK(k.added != PCR_ADDED_NONE && k.added < PCR_ADDED_COUNT);
                }
                break;
            }
            case PathKind::Event:
                RT_CHECK(k.kind == KeyKind::Event);
                RT_CHECK(sameFile(p, k));
                RT_CHECK(eq(k.event, p.name));
                RT_CHECK_EQ((int)k.event_index, (int)p.index);
                RT_CHECK_EQ((int)k.actor, (int)p.actor);
                RT_CHECK_EQ((int)k.action, (int)p.action);
                break;
            case PathKind::Rel:
                RT_CHECK(k.kind == KeyKind::Code && k.src == CodeSource::Rel);
                RT_CHECK(eq(k.file, p.file));
                RT_CHECK_EQ(k.offset, p.offset);
                break;
            case PathKind::MainDol:
                RT_CHECK(k.kind == KeyKind::Code && k.src == CodeSource::MainDol);
                RT_CHECK_EQ(k.offset, p.offset);
                break;
            case PathKind::CustomSymbol:
                RT_CHECK(k.kind == KeyKind::Code && k.src == CodeSource::CustomSymbol);
                RT_CHECK(eq(k.file, p.name));
                break;
            }
        }
    }
    RT_CHECK_EQ(location_keys(-1).size, (size_t)0);
    RT_CHECK_EQ(location_keys(PCR_LOC_COUNT).size, (size_t)0);
    RT_CHECK(location_info(PCR_LOC_COUNT) == nullptr);
}

void testClasses() {
    std::map<std::string, int> got;
    char buf[64];
    for (int loc = 0; loc < PCR_LOC_COUNT; loc++) {
        got[location_class_name(loc, buf, sizeof buf)]++;
        // Classes are the union of the key kinds.
        uint8_t want = 0;
        for (const LocKey& k : location_keys(loc)) {
            switch (k.kind) {
            case KeyKind::Dzx:
                want |= k.tag[0] == 'T' ? PCR_CLASS_CHEST : k.tag[0] == 'A' ? PCR_CLASS_ACTR : PCR_CLASS_SCOB;
                break;
            case KeyKind::Added: want |= PCR_CLASS_ADDED; break;
            case KeyKind::Event: want |= PCR_CLASS_EVENT; break;
            case KeyKind::Code: want |= k.src == CodeSource::CustomSymbol ? PCR_CLASS_CUSTOM : PCR_CLASS_CODE; break;
            }
        }
        RT_CHECK_EQ(location_info(loc)->classes, want);
    }
    const std::map<std::string, int> expected = {
        {"CHEST", 166}, {"SCOB", 57},       {"ACTR", 14}, {"ACTR+CODE", 7},   {"EVENT", 10},
        {"EVENT+CODE", 1}, {"CODE", 58}, {"CODE+CUSTOM", 1}, {"CUSTOM", 2}, {"ADDED+CODE", 4},
    };
    RT_CHECK(got == expected);
    for (const auto& [name, n] : got) {
        if (expected.count(name) == 0 || expected.at(name) != n) {
            std::fprintf(stderr, "class %s: %d\n", name.c_str(), n);
        }
    }
    RT_CHECK(eq(location_class_name(PCR_LOC_OUTSET_ISLAND_ORCA_GIVE_10_KNIGHTS_CRESTS, buf, sizeof buf), "EVENT+CODE"));
    RT_CHECK(eq(location_class_name(PCR_LOC_COUNT, buf, sizeof buf), ""));
    char small[4];
    location_class_name(PCR_LOC_OUTSET_ISLAND_ORCA_GIVE_10_KNIGHTS_CRESTS, small, sizeof small);
    RT_CHECK(std::strlen(small) < sizeof small);
}

void testFingerprints() {
    int dzxItem = 0, dzxOther = 0, events = 0, codeItem = 0, codeOther = 0, custom = 0, added = 0;
    for (const LocKey& k : location_keys()) {
        switch (k.kind) {
        case KeyKind::Dzx:
            if (k.flags & KEY_FP_ITEM) {
                dzxItem++;
                RT_CHECK_EQ(k.disc_byte, k.vanilla);
            } else {
                dzxOther++;
                RT_CHECK(k.field == DzxField::BossItem || k.field == DzxField::TsuboItem ||
                         k.field == DzxField::HomenItem || k.field == DzxField::DekuItem);
            }
            break;
        case KeyKind::Event:
            events++;
            RT_CHECK(k.flags & KEY_FP_ITEM);
            if (eq(k.action_name, "059get_dance")) {
                RT_CHECK_EQ(k.prm0, k.vanilla - 0x6D);
            } else {
                // One vanilla action is spelled "011_get_item"; the player reads only the first 3 digits.
                RT_CHECK(eq(k.action_name, "011get_item") || eq(k.action_name, "011_get_item") ||
                         eq(k.action_name, "046pget"));
                RT_CHECK_EQ(k.prm0, (int32_t)k.vanilla);
            }
            break;
        case KeyKind::Code:
            if (k.src == CodeSource::CustomSymbol) {
                custom++;
            } else if (k.flags & KEY_FP_ITEM) {
                codeItem++;
                RT_CHECK_EQ(k.disc_byte, k.vanilla);
            } else {
                codeOther++;
                RT_CHECK(k.src == CodeSource::Rel);
                RT_CHECK(k.disc_byte != k.vanilla);
            }
            break;
        case KeyKind::Added: added++; break;
        }
    }
    RT_CHECK_EQ(dzxItem, 391);
    RT_CHECK_EQ(dzxOther, 24 - 5); // ACTR paths minus the 5 d_a_item ones
    RT_CHECK_EQ(events, 11);
    RT_CHECK_EQ(codeItem, 70 + 7);
    RT_CHECK_EQ(codeOther, 6); // the boss Heart Container sites
    RT_CHECK_EQ(custom, 3);
    RT_CHECK_EQ(added, 4);
}

void testFields() {
    struct F {
        DzxField f;
        uint8_t off, width;
        uint32_t mask;
    };
    static const F kFields[] = {
        {DzxField::TboxItem, 0x1C, 2, 0xFF00},     {DzxField::ItemItem, 0x08, 4, 0xFF},
        {DzxField::BossItem, 0x08, 4, 0xFF00},     {DzxField::TsuboItem, 0x1C, 2, 0xFF00},
        {DzxField::HomenItem, 0x18, 2, 0x00FF},    {DzxField::SalvageItem, 0x08, 4, 0x0FF0},
        {DzxField::TagKbItem, 0x08, 4, 0xFF},      {DzxField::DekuItem, 0x08, 4, 0xFF},
    };
    std::map<int, int> seen;
    for (const LocKey& k : location_keys()) {
        if (k.kind != KeyKind::Dzx) {
            continue;
        }
        seen[(int)k.field]++;
        bool found = false;
        for (const F& f : kFields) {
            if (f.f == k.field) {
                found = true;
                RT_CHECK_EQ(k.word_off, f.off);
                RT_CHECK_EQ(k.width, f.width);
                RT_CHECK_EQ(k.mask, f.mask);
            }
        }
        RT_CHECK(found);
        // Chests live in TRE chunks, the SCOB classes in SCO chunks, the rest in ACT chunks.
        if (k.field == DzxField::TboxItem) {
            RT_CHECK(k.tag[0] == 'T');
        } else if (k.field == DzxField::SalvageItem || k.field == DzxField::TagKbItem) {
            RT_CHECK(k.tag[0] == 'S');
        } else {
            RT_CHECK(k.tag[0] == 'A');
        }
    }
    // Locations report: 182 chests on disc, 203 salvage + 1 dig, 5 d_a_item, 7 pots, 2 stone heads,
    // 8 boss items, 2 itemDek.
    RT_CHECK_EQ(seen[(int)DzxField::TboxItem], 182);
    RT_CHECK_EQ(seen[(int)DzxField::SalvageItem], 203);
    RT_CHECK_EQ(seen[(int)DzxField::TagKbItem], 1);
    RT_CHECK_EQ(seen[(int)DzxField::ItemItem], 5);
    RT_CHECK_EQ(seen[(int)DzxField::TsuboItem], 7);
    RT_CHECK_EQ(seen[(int)DzxField::HomenItem], 2);
    RT_CHECK_EQ(seen[(int)DzxField::BossItem], 8);
    RT_CHECK_EQ(seen[(int)DzxField::DekuItem], 2);
}

void testIds() {
    std::set<std::string> names;
    for (int loc = 0; loc < PCR_LOC_COUNT; loc++) {
        const LocInfo* info = location_info(loc);
        RT_CHECK(info != nullptr);
        if (info == nullptr) {
            continue;
        }
        RT_CHECK(names.insert(info->enum_name).second);
        std::string want = enumFor(locations()[loc].name);
        if (want != info->enum_name) {
            std::fprintf(stderr, "loc %d: %s != %s\n", loc, info->enum_name, want.c_str());
        }
        RT_CHECK(want == info->enum_name);
    }
    RT_CHECK_EQ((int)PCR_LOC_OUTSET_ISLAND_UNDERNEATH_LINKS_HOUSE,
                location_index("Outset Island - Underneath Link's House"));
    RT_CHECK_EQ((int)PCR_LOC_OUTSET_ISLAND_ORCA_GIVE_10_KNIGHTS_CRESTS,
                location_index("Outset Island - Orca - Give 10 Knight's Crests"));
    RT_CHECK_EQ((int)PCR_LOC_WINDFALL_ISLAND_ZUNARI_STOCK_EXOTIC_FLOWER_IN_ZUNARIS_SHOP,
                location_index("Windfall Island - Zunari - Stock Exotic Flower in Zunari's Shop"));
    RT_CHECK_EQ((int)PCR_LOC_OUTSET_ISLAND_JABUNS_CAVE, location_index("Outset Island - Jabun's Cave"));
    RT_CHECK(eq(location_info(PCR_LOC_OUTSET_ISLAND_DIG_UP_BLACK_SOIL)->enum_name,
                "PCR_LOC_OUTSET_ISLAND_DIG_UP_BLACK_SOIL"));

    // Spot values from the locations report's table.
    Span<LocKey> k = location_keys(PCR_LOC_OUTSET_ISLAND_UNDERNEATH_LINKS_HOUSE);
    RT_CHECK(k.size == 1 && k[0].kind == KeyKind::Dzx && eq(k[0].stage, "LinkUG") && eq(k[0].arc, "Stage") &&
             eq(k[0].tag, "TRES") && k[0].index == 0 && k[0].disc_byte == 0x06 &&
             std::memcmp(k[0].fp_name, "takara2", 8) == 0);
    k = location_keys(PCR_LOC_OUTSET_ISLAND_DIG_UP_BLACK_SOIL);
    RT_CHECK(k.size == 1 && k[0].field == DzxField::TagKbItem && eq(k[0].stage, "sea") && eq(k[0].arc, "Room44") &&
             eq(k[0].tag, "SCOB") && k[0].index == 58 && k[0].disc_byte == 0x07);
    k = location_keys(PCR_LOC_OUTSET_ISLAND_ORCA_GIVE_10_KNIGHTS_CRESTS);
    RT_CHECK(k.size == 2 && k[0].kind == KeyKind::Code && k[1].kind == KeyKind::Event);
    if (k.size == 2) {
        RT_CHECK(eq(k[1].event, "Ji1_TeachSpRollCut") && k[1].event_index == 13 && k[1].gaction == 284 &&
                 k[1].int_index == 143 && eq(k[1].action_name, "046pget") && k[1].prm0 == 170);
    }
    int tott = location_index("Windfall Island - Tott - Teach Rhythm");
    k = location_keys(tott);
    RT_CHECK(k.size == 1 && eq(k[0].action_name, "059get_dance") && k[0].prm0 == 5 && k[0].gaction == 3141);
    int transparent = location_index("Windfall Island - Transparent Chest");
    k = location_keys(transparent);
    RT_CHECK(k.size == 3 && eq(k[0].tag, "TRE1") && eq(k[1].tag, "TRE3") && eq(k[2].tag, "TRE5"));
    k = location_keys(PCR_LOC_OUTSET_ISLAND_JABUNS_CAVE);
    RT_CHECK(k.size == 2 && k[0].src == CodeSource::MainDol && k[0].offset == 0x8035BD39u &&
             k[1].kind == KeyKind::Added && k[1].added == PCR_ADDED_JABUN_CHEST && eq(k[1].stage, "Pjavdou"));
}

void testHelpers() {
    const LocKey* chest = &location_keys(PCR_LOC_OUTSET_ISLAND_UNDERNEATH_LINKS_HOUSE)[0];
    uint8_t e[0x24] = {};
    std::memcpy(e, chest->fp_name, 8);
    e[0x1C] = 0x06; // z_rot 0x06FF
    e[0x1D] = 0xFF;
    RT_CHECK_EQ(dzx_key_read(*chest, e), 0x06u);
    RT_CHECK(dzx_key_fingerprint_ok(*chest, e));
    dzx_key_write(*chest, e, 0x31);
    RT_CHECK_EQ(e[0x1C], 0x31);
    RT_CHECK_EQ(e[0x1D], 0xFF); // the low byte is kept
    RT_CHECK(!dzx_key_fingerprint_ok(*chest, e)); // item changed
    dzx_key_write(*chest, e, 0x06);
    e[3] ^= 1;
    RT_CHECK(!dzx_key_fingerprint_ok(*chest, e)); // name changed

    // Salvage: params bits 4-11.
    const LocKey* salv = nullptr;
    for (const LocKey& k : location_keys()) {
        if (k.kind == KeyKind::Dzx && k.field == DzxField::SalvageItem) {
            salv = &k;
            break;
        }
    }
    RT_CHECK(salv != nullptr);
    if (salv != nullptr) {
        uint8_t s[0x24] = {};
        s[8] = 0x12;
        s[9] = 0x34;
        s[10] = 0x5A;
        s[11] = 0xBC;
        RT_CHECK_EQ(dzx_key_read(*salv, s), 0xABu);
        dzx_key_write(*salv, s, 0x7E);
        RT_CHECK_EQ(s[8], 0x12);
        RT_CHECK_EQ(s[9], 0x34);
        RT_CHECK_EQ(s[10], 0x57);
        RT_CHECK_EQ(s[11], 0xEC);
        RT_CHECK_EQ(dzx_key_read(*salv, s), 0x7Eu);
    }
    // A non-Dzx key never matches a fingerprint.
    const LocKey* code = &location_keys(PCR_LOC_OUTSET_ISLAND_GREAT_FAIRY)[0];
    RT_CHECK(code->kind == KeyKind::Code);
    RT_CHECK(!dzx_key_fingerprint_ok(*code, e));
}

} // namespace

int main() {
    testShape();
    testClasses();
    testFingerprints();
    testFields();
    testIds();
    testHelpers();
    return rt::finish();
}
